<?php declare(strict_types=1); namespace Tests\Unit; use Modules\PromptEngine\Exceptions\{InvalidCharacterException,UnsupportedPlatformException}; use Modules\PromptEngine\Services\{CharacterValidationService,TemplateLoaderService}; use Tests\TestCase; final class PromptEngineCoreTest extends TestCase { public function test_unicode_validation_and_defaults():void{$d=(new CharacterValidationService)->validate(['character'=>'福']);$this->assertSame('福',$d->character);$this->assertSame('gemini',$d->platform);} public function test_latin_and_multiple_characters_are_rejected():void{$this->expectException(InvalidCharacterException::class);(new CharacterValidationService)->validate(['character'=>'AB']);} public function test_unsupported_platform_is_rejected():void{$this->expectException(UnsupportedPlatformException::class);(new CharacterValidationService)->validate(['character'=>'龍','platform'=>'bad']);} public function test_unknown_style_falls_back():void{$d=(new CharacterValidationService)->validate(['character'=>'学','style'=>'bad']);$this->assertSame('museum-editorial',$d->style);} public function test_template_replacement():void{$out=$this->app->make(TemplateLoaderService::class)->load('output/vietnamese-explanation',['MEANING_VI'=>'Phúc lành'],['MEANING_VI']);$this->assertStringContainsString('Phúc lành',$out);} }
